function formatDataForExcelString(dataArray) {
	// Define the headers
	const headers = ["单位", "招牌岗位", "姓名", "成绩"];

	// Start with the header row, columns separated by tabs
	let excelString = headers.join("\t") + "\n";

	// Iterate over each object in the input dataArray
	dataArray.forEach((item) => {
		if (item && item.jsonContent) {
			const jsonContent = item.jsonContent;
			const rowValues = [
				jsonContent.company || "", // "单位" (use empty string if undefined)
				jsonContent.employ || "", // "招牌岗位"
				jsonContent.name || "", // "姓名"
				jsonContent.grade || "", // "成绩"
			];
			// Join row values with tabs and add a newline at the end
			excelString += rowValues.join("\t") + "\n";
		}
	});

	return excelString;
}

